#!/usr/bin/env python3
"""Generates the typed REST client and WebSocket messages from spec/.

    python3 tools/codegen/generate.py          # rewrite the generated files
    python3 tools/codegen/generate.py --check  # exit 1 if they are out of date

Needs PyYAML (`python3-yaml`, or pip in a virtual environment). Generated files start with a
"Generated by" banner; edit this script, not them.

Mapping rules:
- Component schemas become structs with the same name and member names, so
  Glaze reads and writes them by reflection. Nested inline objects become
  structs named after their parent and property.
- Required, non-nullable properties are plain members; everything else is
  std::optional, which also keeps absent fields out of request bodies.
- String enums become `enum class` types with an `Unknown` value, so a new
  server value never fails a response. Identical value sets share one type.
- Free-form objects, inline or a `$ref` to an empty `{type: object}`
  component, become RawJson. Integers are int64.
- Each operation becomes a KalshiClient method named after its operationId.
  Path parameters are arguments, query parameters are a `...Params` struct,
  and a JSON body is its request schema. An optional body is the same
  `const Body&`; passing `{}` sends an empty object. Responses with a single
  property are unwrapped to that property's type.

tools/codegen/ws.py maps spec/asyncapi.yaml the same way.
"""

from __future__ import annotations

import argparse
import re
import sys
from dataclasses import dataclass
from pathlib import Path

try:
    import yaml
except ImportError:  # pragma: no cover - guidance for developers
    sys.exit("PyYAML is required: install python3-yaml, or pip install pyyaml in a virtual environment")

from common import (ROOT, EnumType, Member, StructType, check_enums, check_identifier, check_schema,
                    clang_format, doc_lines, emit_enum, emit_enum_adapter, emit_enum_parser, emit_struct,
                    enumerator, load_contract_yaml, first_sentence, ordered_structs, pascal, ref_name, snake)
from ws import WS_SPEC, WsGenerator

SPEC = ROOT / "spec" / "openapi.yaml"

# Prose-only requirements in the captured contract; keep vendor YAML unchanged.
REQUIRED_ALTERNATIVES = {
    "SetEventContractExitTriggerRequest": ("stop_loss_price", "take_profit_price"),
}

# Schemas where prose requires exactly one of two optional fields to be set.
EXACTLY_ONE_ALTERNATIVES = {
    "DecreaseOrderV2Request": ("reduce_by", "reduce_to"),
}

# Schemas where prose allows at most one of each optional field pair to be set.
AT_MOST_ONE_ALTERNATIVES = {
    "CreateRFQBatchChild": (("contracts_fp", "target_cost_dollars"),),
    "CreateRFQBatchRequest": (("contracts_fp", "target_cost_dollars"),),
    "ProposeBlockTradeRequest": (
        ("buyer_subtrader_id", "buyer_subaccount"),
        ("seller_subtrader_id", "seller_subaccount"),
    ),
}

# Schemas with custom prose-only cross-field or charset rules in validate_header().
CUSTOM_PROSE_VALIDATORS = {
    "CreateRFQBatchChild",
    "CreateRFQBatchRequest",
    "CreateOrderV2Request",
    "CreateOrderWithExitTriggerRequest",
    "GetMarketsParams",
    "GetWeatherIndexParams",
    "GetHistoricalMarketsParams",
}

# Custom prose validators whose default-constructed value fails validation.
CUSTOM_DEFAULT_INVALID = {
    "CreateRFQBatchChild",
    "CreateRFQBatchRequest",
}
BANNER = "// Generated by tools/codegen/generate.py from spec/openapi.yaml. Do not edit.\n"

SERVERS_NOTE = "KalshiClient sends every operation to its one base URL"

HTTP_METHODS = ("get", "post", "put", "delete")
# Methods HttpMethod lacks. An operation using one stops the run instead of vanishing.
UNSUPPORTED_METHODS = ("patch", "head", "options", "trace")

# Keywords that may sit beside a one-member allOf without changing its C++ type:
# notes, and validation the generator does not emit anywhere.
ALL_OF_SIBLINGS = {"allOf", "description", "nullable", "default", "example", "examples", "deprecated", "title",
                   "readOnly", "writeOnly", "externalDocs", "format", "pattern", "minLength", "maxLength",
                   "minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "multipleOf", "minItems",
                   "maxItems", "uniqueItems", "minProperties", "maxProperties"}

# Member kinds that hold several values.
COLLECTION_KINDS = ("vector", "container", "map")

# type_of() marks fixed-point strings that sit inside nested arrays or maps with this, because
# request validation checks only fixed-point values and arrays of them.
DEEP_FIXED_POINT = "<nested>"

# Keywords that give a property its own type, which a `$ref` in another allOf part would contradict.
TYPE_KEYWORDS = {"type", "properties", "items", "additionalProperties", "enum", "allOf"}

# Methods whose operationId carries a version suffix the SDK does not need.
METHOD_RENAMES = {
    "CreateOrderV2": "create_order",
    "CancelOrderV2": "cancel_order",
    "AmendOrderV2": "amend_order",
    "DecreaseOrderV2": "decrease_order",
    "BatchCreateOrdersV2": "batch_create_orders",
    "BatchCancelOrdersV2": "batch_cancel_orders",
    "ListFCMSubtraders": "get_fcm_subtraders",
}

# Property names too generic to name an enum on their own.
GENERIC_ENUM_PROPERTIES = {"status", "type", "result", "market_result", "filter", "incentive_type"}

# Shared names for common inline enum value sets.
ENUM_NAMES_BY_VALUES = {
    frozenset({"yes", "no"}): "Side",
    frozenset({"buy", "sell"}): "Action",
}

# Public names for inline enums, keyed by owner schema plus property. Other
# enums are named in spec order, so without a pin a new or reordered schema can
# take an existing type's name. An unused pin stops the generator.
ENUM_NAMES_BY_CONTEXT = {
    "MarketResult": "MarketResult",
    "SettlementMarketResult": "SettlementMarketResult",
    "MarketStrikeType": "StrikeType",
    "CreateWeatherPointMarketRequestStrikeType": "WeatherPointStrikeType",
}


@dataclass
class Operation:
    operation_id: str
    method_name: str
    http_method: str
    path: str
    tag: str
    summary: str
    deprecated: bool
    path_params: list[str]
    params_struct: StructType | None
    query: list[tuple[str, Member]]
    body_type: str | None
    empty_body: bool  # the operation takes an empty JSON object
    response_type: str | None  # None means Result<void>
    unwrap_member: str | None


class Generator:
    def __init__(self, spec: dict, enum_pins: dict[str, str] | None = None) -> None:
        self.spec = spec
        self.enum_pins = dict(ENUM_NAMES_BY_CONTEXT if enum_pins is None else enum_pins)
        self.used_pins: set[str] = set()
        self.schemas: dict = spec["components"]["schemas"]
        self.parameters: dict = spec["components"].get("parameters", {})
        self.enums: dict[str, EnumType] = {}
        self.enum_by_values: dict[frozenset, str] = {}
        self.structs: dict[str, StructType] = {}
        self.struct_schemas: dict[str, dict] = {}
        self.aliases: dict[str, str] = {}
        self.fixed_point_items: dict[str, str] = {}  # array alias -> its fixed-point item type
        self.operations: list[Operation] = []
        self.request_bodies: set[str] = set()
        self.query_param_structs: set[str] = set()

    # ----- types -----------------------------------------------------------

    def flatten_compositions(self) -> None:
        """Merge object extensions, rejecting conflicting or non-object members."""
        source = self.schemas
        resolved = {}

        def flatten(name: str, active: set[str]) -> dict:
            if name in resolved:
                return resolved[name]
            if name in active:
                raise SystemExit(f"{name}: cyclic allOf composition")
            schema = source[name]
            if len(schema.get("allOf", [])) < 2:
                return schema
            if set(schema) - {"allOf", "description", "type"}:
                raise SystemExit(f"{name}: unsupported fields beside object allOf")
            properties = {}
            required = []
            for part in schema["allOf"]:
                if "$ref" in part:
                    if set(part) != {"$ref"} or not part["$ref"].startswith("#/components/schemas/"):
                        raise SystemExit(f"{name}: unsupported allOf reference")
                    part = flatten(ref_name(part["$ref"]), active | {name})
                if part.get("type") != "object" or {k for k in part if not k.startswith("x-")} - {"type", "properties", "required", "description", "additionalProperties", "example", "examples", "title", "deprecated", "externalDocs"}:
                    raise SystemExit(f"{name}: allOf members must be plain objects")
                if part.get("additionalProperties", False) is not False:
                    raise SystemExit(f"{name}: allOf map extensions are not supported")
                for field, value in part.get("properties", {}).items():
                    merged = dict(properties.get(field, {}))
                    # A $ref and an inline type share no keys, so the key check below would let
                    # the $ref win silently.
                    if field in properties and ("$ref" in merged) != ("$ref" in value):
                        inline = value if "$ref" in merged else merged
                        if TYPE_KEYWORDS & set(inline):
                            raise SystemExit(f"{name}.{field}: incompatible allOf fields")
                    for key, entry in value.items():
                        metadata = key.startswith("x-") or key in {"description", "example", "examples", "title", "deprecated", "externalDocs"}
                        if key in merged and merged[key] != entry and not metadata:
                            raise SystemExit(f"{name}.{field}: incompatible allOf fields")
                        merged[key] = entry
                    properties[field] = merged
                required.extend(v for v in part.get("required", []) if v not in required)
            resolved[name] = {"type": "object", "properties": properties, "required": required,
                              "description": schema.get("description", "")}
            return resolved[name]

        self.schemas = {name: flatten(name, set()) for name in source}

    def run(self) -> None:
        self.flatten_compositions()
        for name, schema in self.schemas.items():
            self.check(schema, name)
            # struct_for reads only `properties`, so a component that is only a
            # reference would become an empty struct.
            if "allOf" in schema or "$ref" in schema:
                raise SystemExit(f"{name}: a component that is an `allOf` or `$ref` is not supported; "
                                 "it would become an empty struct")
            if schema.get("additionalProperties", False) is not False and not schema.get("properties"):
                raise SystemExit(f"{name}: top-level map schemas are not supported; it would become an empty struct")
            # `{type: object}` alone is an intentional empty body; without a type it is any value.
            if "type" not in schema and "enum" not in schema and not schema.get("properties"):
                raise SystemExit(f"{name}: a component with no `type` or `properties` is not supported; "
                                 "it would become an empty struct")
        for name, schema in self.schemas.items():
            if "enum" in schema:
                self.enum_for(schema["enum"], name, schema.get("description", ""), fixed=name)
            elif schema.get("type") in ("string", "integer", "number", "boolean"):
                self.aliases[name] = self.primitive(schema)
        for name, schema in self.schemas.items():
            if schema.get("type") == "array":
                inner, kind, _, fixed_point, _ = self.type_of(self.element(schema.get("items", {}), name + "Item"),
                                                              name + "Item")
                if kind not in ("scalar", "string"):
                    raise SystemExit(f"{name}: component arrays with composite or enum items are not supported")
                size = schema.get("minItems")
                fixed = size is not None and size == schema.get("maxItems")
                self.aliases[name] = f"std::array<{inner}, {size}>" if fixed else f"std::vector<{inner}>"
                if fixed_point:
                    self.fixed_point_items[name] = fixed_point
        for name, schema in self.schemas.items():
            if name not in self.enums and name not in self.aliases and not self.empty_object(schema):
                self.struct_for(name, schema)
        for path, item in self.spec["paths"].items():
            if "$ref" in item:
                raise SystemExit(f"{path}: path item $ref is not supported")
            if "servers" in item:
                raise SystemExit(f"{path}: `servers` overrides are not supported; {SERVERS_NOTE}")
            for method in UNSUPPORTED_METHODS:
                if method in item:
                    raise SystemExit(f"{method.upper()} {path}: HttpMethod has no {method.upper()}; "
                                     "add it to the runtime and the generator first")
            for method in HTTP_METHODS:
                if method in item:
                    self.operation(path, method, item[method], item.get("parameters", []))
        self.check_request_fields()
        if unused := sorted(set(self.enum_pins) - self.used_pins):
            raise SystemExit(f"enum name pins {unused} match no inline enum; update ENUM_NAMES_BY_CONTEXT")
        check_enums(self.enums)

    @staticmethod
    def property_not_supported(schema: dict) -> bool:
        """Required enum/integer conjunctions can be checked without changing the type."""
        rule = schema.get("not", {})
        if not isinstance(rule, dict) or schema.get("type") != "object" or set(rule) != {"properties", "required"}:
            return False
        properties = rule["properties"]
        if not properties or set(properties) != set(rule["required"]):
            return False
        if not set(properties) <= set(schema.get("required", [])):
            return False
        for name, constraint in properties.items():
            prop = schema.get("properties", {}).get(name, {})
            if prop.get("nullable"):
                return False
            if set(constraint) == {"enum"}:
                if prop.get("type") != "string" or not constraint["enum"]:
                    return False
                if not all(isinstance(v, str) and v in prop.get("enum", []) for v in constraint["enum"]):
                    return False
            elif set(constraint) == {"minimum"}:
                if prop.get("type") != "integer" or type(constraint["minimum"]) is not int:
                    return False
                if any(type(prop[k]) is not int for k in ("minimum", "maximum") if k in prop):
                    return False
            else:
                return False
        return True

    @staticmethod
    def check(schema: dict, where: str) -> None:
        checked = {k: v for k, v in schema.items() if k != "not"} if Generator.property_not_supported(schema) else schema
        check_schema(checked, where, max_all_of=1)
        if isinstance(schema.get("type"), list):
            raise SystemExit(f"{where}: `type` lists (OpenAPI 3.1) are not supported here; ws.py has them")
        # unwrap() keeps only `nullable` from beside a one-member allOf, and member()
        # reads `readOnly`. Anything else there, such as `properties`, would vanish.
        # Vendor extensions (x-...) are hints for other tools and change nothing.
        if "allOf" in schema and (extra := sorted(k for k in set(schema) - ALL_OF_SIBLINGS if not k.startswith("x-"))):
            raise SystemExit(f"{where}: {extra} beside `allOf` is not supported; it would be dropped")
        # struct_for reads `required` only for declared properties, so any other name would be ignored.
        required = schema.get("required")
        if isinstance(required, list) and (missing := [n for n in required if n not in schema.get("properties", {})]):
            raise SystemExit(f"{where}: `required` names {missing}, which `properties` does not declare")

    def element(self, schema: dict, where: str) -> dict:
        """Array items and map values have no std::optional form, so a null one would fail decode()."""
        if self.unwrap(schema).get("nullable") or schema.get("nullable"):
            raise SystemExit(f"{where}: nullable array items and map values are not supported")
        return schema

    @staticmethod
    def empty_object(schema: dict) -> bool:
        return schema.get("type") == "object" and not schema.get("properties") and not schema.get("additionalProperties")

    def check_request_fields(self) -> None:
        """Stops on request fields that validation would get wrong or skip.

        A required read-only field would fail validation whenever it is empty, and validate()
        does not look inside nested arrays or maps for fixed-point strings or for structs that
        need validation.
        """
        pending, seen = sorted(self.request_bodies), set()
        while pending:
            name = pending.pop()
            if name in seen or name not in self.structs:
                continue
            seen.add(name)
            for m in self.structs[name].members:
                if m.read_only and m.required:
                    raise SystemExit(f"{name}.{m.json_name}: required readOnly fields in request bodies "
                                     "are not supported")
                if m.fixed_point_deep:
                    raise SystemExit(f"{name}.{m.json_name}: validation cannot check fixed-point strings "
                                     "inside nested arrays or maps in request bodies")
                if m.nested_element in self.structs and self.needs_validation(m.nested_element):
                    raise SystemExit(f"{name}.{m.json_name}: validation cannot check {m.nested_element} "
                                     "inside nested arrays or maps in request bodies")
                pending.extend((m.element, m.nested_element))

    def enum_for(self, values: list, context: str, doc: str, fixed: str | None = None,
                 prop: str = "") -> str:
        if not all(isinstance(v, str) for v in values):
            raise SystemExit(f"{fixed or context}: only string enums are supported; found {values}")
        key = frozenset(values)
        if pinned := self.enum_pins.get(context):
            existing = self.enums.get(pinned)
            if existing is not None and frozenset(existing.values) != key:
                raise SystemExit(f"{context}: pinned enum {pinned} already has values {existing.values}")
            if existing is None:
                self.enums[pinned] = EnumType(pinned, list(values), first_sentence(doc))
                self.enum_by_values.setdefault(key, pinned)
            self.used_pins.add(context)
            return pinned
        reserved = set(self.enum_pins.values())
        if fixed:
            self.enums[fixed] = EnumType(fixed, list(values), first_sentence(doc))
            self.enum_by_values.setdefault(key, fixed)
            return fixed
        # A named enum whose name matches the property (outcome_side ->
        # OutcomeSide) wins over the shared names below.
        for enum in self.enums.values():
            if frozenset(enum.values) == key and prop and prop.endswith(snake(enum.name)):
                return enum.name
        name = ENUM_NAMES_BY_VALUES.get(key)
        if name in self.enums:
            return name
        if name is None and key in self.enum_by_values:
            return self.enum_by_values[key]
        if name is None:
            specific = prop and prop not in GENERIC_ENUM_PROPERTIES and not prop.endswith("_filter")
            name = pascal(prop) if specific and pascal(prop) not in self.enums.keys() | reserved else context
        while name in self.enums or name in self.schemas or name in reserved:
            name += "Value"
        self.enums[name] = EnumType(name, list(values), first_sentence(doc))
        self.enum_by_values.setdefault(key, name)
        return name

    @staticmethod
    def primitive(schema: dict) -> str:
        kind = schema.get("type")
        if kind == "integer":
            return "std::int64_t"
        if kind == "number":
            return "double"
        if kind == "boolean":
            return "bool"
        return "std::string"

    def unwrap(self, schema: dict) -> dict:
        while "allOf" in schema and len(schema["allOf"]) == 1:
            nullable = schema.get("nullable", False)
            schema = dict(schema["allOf"][0], nullable=nullable or schema["allOf"][0].get("nullable", False))
        return schema

    def type_of(self, schema: dict, context: str, prop: str = "",
                parameter: bool = False) -> tuple[str, str, str, str, str]:
        """Returns (cpp type, kind, element name, fixed point, nested element).

        The fixed point entry names the FixedPoint alias the value or, for an array, each item
        is; DEEP_FIXED_POINT means fixed-point strings inside nested arrays or maps. The nested
        element names a struct or enum held inside nested arrays or maps, such as `Leg` in
        `std::vector<std::vector<Leg>>` or `std::map<std::string, Leg>`, which validate()
        does not reach. `parameter` marks query parameters, which send integer enums as numbers.
        """
        self.check(schema, context)
        schema = self.unwrap(schema)
        self.check(schema, context)
        if "$ref" in schema:
            name = ref_name(schema["$ref"])
            if name in self.enums:
                return name, "enum", name, "", ""
            if name in self.aliases:
                if self.aliases[name].startswith(("std::array", "std::vector")):
                    return name, "container", "", self.fixed_point_items.get(name, ""), ""
                kind = "string" if self.aliases[name] == "std::string" else "scalar"
                return name, kind, "", name if name.startswith("FixedPoint") else "", ""
            # run() emits no struct for an empty `{type: object}` component. Like an inline
            # empty object, it declares no members and allows any, so it is RawJson.
            if self.empty_object(self.schemas.get(name, {})):
                return "RawJson", "raw", "", "", ""
            return name, "struct", name, "", ""
        if "enum" in schema and schema.get("type", "string") == "string":
            name = self.enum_for(schema["enum"], context, schema.get("description", ""), prop=prop)
            return name, "enum", name, "", ""
        if "enum" in schema and not parameter:
            # A query parameter sends the number as given. A member would become a plain
            # std::int64_t that accepts any value, dropping the value set.
            raise SystemExit(f"{context}: only string enums are supported outside query parameters; "
                             f"found {schema['enum']}")
        kind = schema.get("type")
        if kind == "array":
            items = self.element(schema.get("items", {}), context + "Item")
            inner, inner_kind, element, inner_fixed, inner_nested = self.type_of(items, context + "Item", prop,
                                                                                 parameter)
            fixed = DEEP_FIXED_POINT if inner_fixed and inner_kind in COLLECTION_KINDS else inner_fixed
            nested = inner_nested or (element if inner_kind in COLLECTION_KINDS else "")
            return (f"std::vector<{inner}>", "vector", element if inner_kind in ("struct", "enum") else "", fixed,
                    nested)
        if kind == "object" or "properties" in schema or "additionalProperties" in schema or not kind:
            if schema.get("properties"):
                # Each inline object is reached once, so an existing name is a clash.
                if context in self.schemas or context in self.structs:
                    raise SystemExit(f"{context}: an inline object has the same name as another schema")
                self.struct_for(context, schema)
                return context, "struct", context, "", ""
            extra = schema.get("additionalProperties")
            if isinstance(extra, dict) and extra:
                inner, _, element, inner_fixed, inner_nested = self.type_of(
                    self.element(extra, context + "Value"), context + "Value", parameter=parameter)
                # validate() checks no map values, so even a direct struct value is nested.
                return (f"std::map<std::string, {inner}>", "map", element, DEEP_FIXED_POINT if inner_fixed else "",
                        inner_nested or element)
            return "RawJson", "raw", "", "", ""
        return self.primitive(schema), "string" if kind == "string" else "scalar", "", "", ""

    def member(self, owner: str, json_name: str, schema: dict, required: bool, parameter: bool = False) -> Member:
        schema_u = self.unwrap(schema)
        cpp, kind, element, fixed, nested = self.type_of(schema, owner + pascal(json_name), json_name, parameter)
        collection = kind in COLLECTION_KINDS
        nullable = bool(schema_u.get("nullable")) or bool(schema.get("nullable"))
        if "$ref" in schema_u:  # a nullable component is nullable wherever it is used
            nullable = nullable or bool(self.schemas.get(ref_name(schema_u["$ref"]), {}).get("nullable"))
        plain = required and not nullable
        check_identifier(owner, json_name)

        def int_bound(key: str) -> int | None:
            for src in (schema, schema_u):
                val = src.get(key)
                if type(val) is int:
                    return val
            return None

        is_int_scalar = kind == "scalar" and (
            cpp == "std::int64_t" or self.aliases.get(cpp) == "std::int64_t"
        )
        return Member(
            json_name=json_name,
            cpp_type=cpp if plain else f"std::optional<{cpp}>",
            doc=schema.get("description") or schema_u.get("description", ""),
            fixed_point=bool(fixed) and not collection,
            fixed_point_items=fixed if collection and fixed != DEEP_FIXED_POINT else "",
            fixed_point_deep=fixed == DEEP_FIXED_POINT,
            nested_element=nested,
            required=plain,
            base_kind=kind,
            element=element,
            read_only=bool(schema.get("readOnly") or schema_u.get("readOnly")),
            minimum=int_bound("minimum") if is_int_scalar else None,
            maximum=int_bound("maximum") if is_int_scalar else None,
            min_items=int_bound("minItems") if kind == "vector" else None,
            max_items=int_bound("maxItems") if kind == "vector" else None,
            min_length=int_bound("minLength") if kind == "string" else None,
            max_length=int_bound("maxLength") if kind == "string" else None,
        )

    def struct_for(self, name: str, schema: dict) -> StructType:
        if name in self.structs:
            return self.structs[name]
        self.check(schema, name)
        if schema.get("additionalProperties", False) is not False and schema.get("properties"):
            raise SystemExit(f"{name}: properties with additionalProperties are not supported; "
                             "the extra keys would be dropped")
        self.struct_schemas[name] = schema
        struct = StructType(name, doc=first_sentence(schema.get("description")))
        self.structs[name] = struct
        required = set(schema.get("required", []))
        for json_name, prop in schema.get("properties", {}).items():
            struct.members.append(self.member(name, json_name, prop, json_name in required))
        return struct

    # ----- operations ------------------------------------------------------

    def parameter(self, param: dict) -> dict:
        if "$ref" not in param:
            return param
        if not re.fullmatch(r"#/components/parameters/[^/]+", param["$ref"]):
            raise SystemExit(f"{param['$ref']} is not a component parameter")
        return self.parameters[ref_name(param["$ref"])]

    @staticmethod
    def check_parameter(op_id: str, param: dict) -> None:
        where = f"{op_id} parameter {param.get('name')}"
        if param.get("in") not in ("path", "query"):
            raise SystemExit(f"{where}: `in: {param.get('in')}` is not supported; "
                             "HttpTransport::request takes only a path and a body")
        if "content" in param:
            raise SystemExit(f"{where}: `content` parameters are not supported; use `schema`")

    def response_result(self, op_id: str, code: str, response: dict) -> tuple[str | None, str | None]:
        """Returns (response type, unwrapped member); a None type means Result<void>."""
        where = f"{op_id} response {code}"
        if "$ref" in response:
            raise SystemExit(f"{where}: $ref responses are not supported")
        content = response.get("content", {})
        if code == "204" or not content:
            return None, None
        if "application/json" not in content:
            raise SystemExit(f"{where}: only application/json is supported; found {sorted(content)}")
        schema = content["application/json"].get("schema")
        if isinstance(schema, dict) and schema.get("type") == "object" and "properties" in schema:
            name = pascal(op_id) + "Response"
            if name in self.schemas and self.schemas[name] != schema:
                raise SystemExit(f"{where}: inline response collides with {name}")
            self.schemas[name] = schema
            self.struct_for(name, schema)
            return name, None
        if schema is None or "$ref" not in schema:
            raise SystemExit(f"{where}: must be a $ref to a component schema")
        check_schema(schema, where, max_all_of=0)
        name = ref_name(schema["$ref"])
        target = self.schemas[name]
        props = target.get("properties", {})
        if target.get("type") == "object" and not props:
            return None, None
        if len(props) == 1:
            member = self.structs[name].members[0]
            return member.cpp_type, member.json_name
        return name, None

    def operation(self, path: str, method: str, op: dict, shared: list) -> None:
        op_id = op.get("operationId")
        if not op_id:
            raise SystemExit(f"{method.upper()} {path}: needs an operationId")
        if "servers" in op:
            raise SystemExit(f"{op_id}: `servers` overrides are not supported; {SERVERS_NOTE}")
        method_name = METHOD_RENAMES.get(op_id, snake(op_id))
        if any(existing.method_name == method_name for existing in self.operations):
            raise SystemExit(f"{op_id}: another operation already maps to {method_name}")
        params = [self.parameter(p) for p in shared + op.get("parameters", [])]
        for p in params:
            self.check_parameter(op_id, p)
        if len({(p["name"], p["in"]) for p in params}) != len(params):
            raise SystemExit(f"{op_id}: a parameter is declared twice; operation-level overrides "
                             "of path-level parameters are not supported")
        path_params = [p["name"] for p in params if p["in"] == "path"]
        in_path = re.findall(r"{([^}]+)}", path)
        if sorted(path_params) != sorted(in_path):
            raise SystemExit(f"{op_id}: path parameters {path_params} do not match {path}")
        query_params = [p for p in params if p["in"] == "query"]
        params_struct = None
        query: list[tuple[str, Member]] = []
        if query_params:
            params_struct = StructType(pascal(method_name) + "Params", doc=f"Query parameters for `{method_name}`.")
            if params_struct.name in self.structs or params_struct.name in self.schemas:
                raise SystemExit(f"{op_id}: {params_struct.name} is already a schema name")
            for p in query_params:
                schema = dict(p.get("schema", {}))
                if not schema.get("description") and p.get("description"):
                    schema["description"] = p["description"]
                m = self.member(pascal(method_name), p["name"], schema, bool(p.get("required")), parameter=True)
                if m.base_kind in ("struct", "map", "raw") or (m.base_kind == "vector" and m.element in self.structs):
                    raise SystemExit(f"{op_id} parameter {p['name']}: detail::Query cannot send {m.cpp_type}")
                # detail::Query repeats the key for each array item, which is form with
                # explode. Scalars read the same whatever the style and explode say.
                if m.base_kind in ("vector", "container") and (
                        p.get("style", "form") != "form" or p.get("explode", True) is not True):
                    raise SystemExit(f"{op_id} parameter {p['name']}: only style: form with explode: true "
                                     "is supported for arrays")
                if m.base_kind == "vector":
                    m.cpp_type = m.cpp_type.removeprefix("std::optional<").removesuffix(">") if not m.required else m.cpp_type
                params_struct.members.append(m)
                query.append((p["name"], m))
            self.structs[params_struct.name] = params_struct
            self.query_param_structs.add(params_struct.name)

        body_type = None
        empty_body = False
        if "requestBody" in op:
            where = f"{op_id} request body"
            if "$ref" in op["requestBody"]:
                raise SystemExit(f"{where}: $ref request bodies are not supported")
            content = op["requestBody"].get("content", {})
            if "application/json" not in content:
                raise SystemExit(f"{where}: only application/json is supported; found {sorted(content)}")
            schema = content["application/json"].get("schema", {})
            check_schema(schema, where, max_all_of=0)
            name = ref_name(schema["$ref"]) if "$ref" in schema else None
            if name in self.structs:
                body_type = name
                self.request_bodies.add(body_type)
            elif name is not None and self.empty_object(self.schemas.get(name, {})):
                empty_body = True
            else:
                raise SystemExit(f"{where}: must be a $ref to a component object")
            # An optional body (OpenAPI's default) still maps to `const Body&`. Callers omit it by
            # passing `{}`, which sends an empty object; that matches no body only when nothing
            # in it is required.
            if body_type and op["requestBody"].get("required") is not True and (
                    body_type in REQUIRED_ALTERNATIVES or body_type in EXACTLY_ONE_ALTERNATIVES or
                    body_type in CUSTOM_DEFAULT_INVALID or
                    any(m.required for m in self.structs[body_type].members)):
                raise SystemExit(f"{where}: an optional body with required fields is not supported; "
                                 f"`const {body_type}&` cannot leave it out")

        responses = {str(code): response for code, response in op.get("responses", {}).items()}
        success = [code for code in responses if code.startswith("2")]
        if not success:
            raise SystemExit(f"{op_id}: has no 2xx response")
        if unsupported := [code for code in success if code not in ("200", "201", "204")]:
            raise SystemExit(f"{op_id}: responses {unsupported} are not supported; use 200, 201, or 204")
        # Any 2xx counts as success, so each must decode as the method's result type.
        results = {code: self.response_result(op_id, code, responses[code]) for code in success}
        if len(set(results.values())) > 1:
            raise SystemExit(f"{op_id}: 2xx responses {sorted(results)} have different bodies")
        response_type, unwrap_member = results[success[0]]

        self.operations.append(Operation(
            operation_id=op_id,
            method_name=method_name,
            http_method=method.upper(),
            path=path,
            tag=(op.get("tags") or ["misc"])[0],
            summary=first_sentence(op.get("summary") or op.get("description")),
            deprecated=bool(op.get("deprecated")),
            path_params=in_path,
            params_struct=params_struct,
            query=query,
            body_type=body_type,
            empty_body=empty_body,
            response_type=response_type,
            unwrap_member=unwrap_member,
        ))

    # ----- emission --------------------------------------------------------

    def ordered_structs(self) -> list[StructType]:
        return ordered_structs(self.structs)

    def models_header(self) -> str:
        out = [BANNER, "#pragma once\n\n#include \"kalshi/raw_json.hpp\"\n\n",
               "#include <array>\n#include <cstdint>\n#include <map>\n#include <optional>\n#include <string>\n",
               "#include <string_view>\n#include <vector>\n\nnamespace kalshi {\n\n"]
        out.append("// ----- Scalars ----------------------------------------------------------\n\n")
        for name, cpp in sorted(self.aliases.items(), key=lambda item: (item[1].startswith(("std::array", "std::vector")), item[0])):
            out.extend(line + "\n" for line in doc_lines(self.schemas[name].get("description", ""), ""))
            out.append(f"using {name} = {cpp};\n\n")
        out.append("// ----- Enums ------------------------------------------------------------\n\n")
        for enum in sorted(self.enums.values(), key=lambda e: e.name):
            out.append(emit_enum(enum))
        out.append("// ----- Models -----------------------------------------------------------\n\n")
        for struct in self.ordered_structs():
            out.append(emit_struct(struct))
        out.append("} // namespace kalshi\n")
        return "".join(out)

    @staticmethod
    def result_type(op: Operation) -> str:
        return f"Result<{op.response_type}>" if op.response_type else "Result<void>"

    def signature(self, op: Operation, qualified: bool) -> str:
        result = self.result_type(op)
        args = [f"std::string_view {name}" for name in op.path_params]
        if op.body_type:
            args.append(f"const {op.body_type}& body")
        if op.params_struct:
            needs_value = any(m.required for m in op.params_struct.members)
            default = "" if needs_value or qualified else " = {}"
            args.append(f"const {op.params_struct.name}& params{default}")
        scope = "KalshiClient::" if qualified else ""
        return f"{result} {scope}{op.method_name}({', '.join(args)})"

    def api_declarations(self) -> str:
        out: list[str] = []
        by_tag: dict[str, list[Operation]] = {}
        for op in self.operations:
            by_tag.setdefault(op.tag, []).append(op)
        for tag in sorted(by_tag):
            out.append(f"\t// ----- {tag} " + "-" * max(4, 66 - len(tag)) + "\n\n")
            for op in by_tag[tag]:
                out.extend(line + "\n" for line in doc_lines(re.sub(r"\s*\(V\d\)$", "", op.summary), "\t"))
                out.append(f"\t/// `{op.http_method} {op.path}`\n")
                attrs = "[[nodiscard]] "
                if op.deprecated:
                    attrs = '[[deprecated("deprecated by Kalshi")]] ' + attrs
                out.append(f"\t{attrs}{self.signature(op, qualified=False)};\n\n")
        return "".join(out)

    def operations_source(self, tag: str, ops: list[Operation]) -> str:
        out = [BANNER, '#include "kalshi/api.hpp"\n\n#include "../support.hpp"\n#include "../validate.hpp"\n\n',
               "namespace kalshi {\n\n"]
        for op in ops:
            out.append(self.signature(op, qualified=True) + " {\n")
            if op.body_type and self.needs_validation(op.body_type):
                out.append(f"\tif (Result<void> valid = detail::validate(body); !valid) {{\n"
                           f"\t\treturn std::unexpected(std::move(valid.error()));\n\t}}\n")
            if op.params_struct and self.needs_validation(op.params_struct.name):
                out.append(f"\tif (Result<void> valid = detail::validate(params); !valid) {{\n"
                           f"\t\treturn std::unexpected(std::move(valid.error()));\n\t}}\n")
            if op.path_params:
                values = ", ".join(op.path_params)
                out.append(f'\tResult<std::string> target = detail::expand_path("{op.path}", {{{values}}});\n'
                           "\tif (!target) {\n\t\treturn std::unexpected(std::move(target.error()));\n\t}\n")
                target = "*target"
            else:
                target = f'std::string{{"{op.path}"}}'
            if op.query:
                out.append(f"\tdetail::Query query({target});\n")
                for name, m in op.query:
                    out.append(f'\tquery.add("{name}", params.{name});\n')
                target = "std::move(query).str()"
            body = "detail::encode(body)" if op.body_type else ('std::string{"{}"}' if op.empty_body else "{}")
            call = f'Impl::send(impl_.get(), HttpMethod::{"DEL" if op.http_method == "DELETE" else op.http_method}, {target}, {body}, "{op.method_name}")'
            if op.response_type is None:
                out.append(f"\treturn detail::expect_success({call});\n")
            elif op.unwrap_member:
                wrapper = self.structs_for_unwrap(op)
                out.append(f"\tResult<{wrapper}> response = detail::decode<{wrapper}>({call});\n"
                           "\tif (!response) {\n\t\treturn std::unexpected(std::move(response.error()));\n\t}\n"
                           f"\treturn {self.take(op.response_type, f'response->{op.unwrap_member}')};\n")
            else:
                out.append(f"\treturn detail::decode<{op.response_type}>({call});\n")
            out.append("}\n\n")
        out.append("} // namespace kalshi\n")
        return "".join(out)

    def take(self, cpp_type: str, expr: str) -> str:
        """Moves out of `expr` unless the type is trivially copyable."""
        trivial = cpp_type in ("std::int64_t", "double", "bool") or cpp_type in self.enums
        return expr if trivial else f"std::move({expr})"

    def structs_for_unwrap(self, op: Operation) -> str:
        path_item = self.spec["paths"][op.path][op.http_method.lower()]
        responses = path_item["responses"]
        ok = next(code for code in ("200", "201") if code in responses)
        return ref_name(responses[ok]["content"]["application/json"]["schema"]["$ref"])

    # Validation of request bodies: fixed-point strings, alone or in arrays, parse;
    # required enums are set; and required strings are non-empty.

    @staticmethod
    def member_has_bounds(m: Member) -> bool:
        return any(v is not None for v in (m.minimum, m.maximum, m.min_items, m.max_items, m.min_length, m.max_length))

    def needs_validation(self, name: str, seen: set[str] | None = None) -> bool:
        seen = seen or set()
        if name in seen or name not in self.structs:
            return False
        seen.add(name)
        if (name in REQUIRED_ALTERNATIVES or name in EXACTLY_ONE_ALTERNATIVES or
                name in AT_MOST_ONE_ALTERNATIVES or name in CUSTOM_PROSE_VALIDATORS or
                "not" in self.struct_schemas.get(name, {})):
            return True
        for m in self.structs[name].members:
            if (m.fixed_point or m.fixed_point_items or self.member_has_bounds(m) or
                    (m.required and m.base_kind in ("enum", "string"))):
                return True
            if m.base_kind in ("struct", "vector") and m.element in self.structs and self.needs_validation(m.element, seen):
                return True
        return False

    def default_is_invalid(self, name: str, seen: set[str] | None = None) -> bool:
        """Whether a default-constructed body or params struct fails validation."""
        seen = seen or set()
        if name in seen or name not in self.structs:
            return False
        seen.add(name)
        if (name in REQUIRED_ALTERNATIVES or name in EXACTLY_ONE_ALTERNATIVES or
                name in CUSTOM_DEFAULT_INVALID):
            return True
        for m in self.structs[name].members:
            if not m.required:
                continue
            if m.fixed_point or m.base_kind in ("enum", "string"):
                return True
            if m.base_kind == "scalar" and (
                    (m.minimum is not None and 0 < m.minimum) or (m.maximum is not None and 0 > m.maximum)):
                return True
            if m.base_kind == "vector" and m.min_items is not None and m.min_items > 0:
                return True
            if m.base_kind == "struct" and m.element in self.structs and self.default_is_invalid(m.element, seen):
                return True
        return False

    @staticmethod
    def emit_custom_prose_checks(name: str) -> str:
        if name == "CreateRFQBatchChild":
            return (
                "\tconst bool has_ticker = value.market_ticker && !value.market_ticker->empty();\n"
                "\tconst bool has_selected = value.selected_markets && !value.selected_markets->empty();\n"
                "\tif (has_ticker == has_selected) {\n"
                '\t\treturn invalid("CreateRFQBatchChild", "fields", "requires exactly one of market_ticker or selected_markets");\n'
                "\t}\n"
            )
        if name == "CreateRFQBatchRequest":
            return (
                "\tif (value.rest_remainder.value_or(false)) {\n"
                '\t\treturn invalid("CreateRFQBatchRequest", "rest_remainder", "must be false");\n'
                "\t}\n"
                "\tconst bool has_batch_size = value.contracts_fp.has_value() || value.target_cost_dollars.has_value();\n"
                "\tfor (const CreateRFQBatchChild& child : value.children) {\n"
                "\t\tif (!has_batch_size && !child.contracts_fp && !child.target_cost_dollars) {\n"
                '\t\t\treturn invalid("CreateRFQBatchRequest", "fields", "requires contracts_fp or target_cost_dollars unless every child sets its own");\n'
                "\t\t}\n"
                "\t\tif (child.selected_markets && !child.selected_markets->empty() && "
                "(!value.mve_collection_ticker || value.mve_collection_ticker->empty())) {\n"
                '\t\t\treturn invalid("CreateRFQBatchRequest", "mve_collection_ticker", "is required when any child uses selected_markets");\n'
                "\t\t}\n"
                "\t}\n"
            )
        if name in ("CreateOrderV2Request", "CreateOrderWithExitTriggerRequest"):
            return (
                "\tif (value.expiration_time && value.time_in_force == TimeInForce::ImmediateOrCancel) {\n"
                f'\t\treturn invalid("{name}", "expiration_time", "cannot be combined with immediate_or_cancel");\n'
                "\t}\n"
                "\tif (value.reduce_only.value_or(false) && value.time_in_force != TimeInForce::ImmediateOrCancel) {\n"
                f'\t\treturn invalid("{name}", "reduce_only", "requires time_in_force to be immediate_or_cancel");\n'
                "\t}\n"
                "\tif (value.client_order_id && !is_valid_client_order_id(*value.client_order_id)) {\n"
                f'\t\treturn invalid("{name}", "client_order_id", "must be at most 64 characters from letters, digits, and _ - : + = /");\n'
                "\t}\n"
            )
        if name == "GetMarketsParams":
            return (
                "\tconst bool created_ts = value.min_created_ts.has_value() || value.max_created_ts.has_value();\n"
                "\tconst bool close_ts = value.min_close_ts.has_value() || value.max_close_ts.has_value();\n"
                "\tconst bool settled_ts = value.min_settled_ts.has_value() || value.max_settled_ts.has_value();\n"
                "\tconst bool updated_ts = value.min_updated_ts.has_value() || value.max_updated_ts.has_value();\n"
                "\tif (static_cast<int>(created_ts) + static_cast<int>(close_ts) + "
                "static_cast<int>(settled_ts) + static_cast<int>(updated_ts) > 1) {\n"
                '\t\treturn invalid("GetMarketsParams", "fields", "timestamp filter groups are mutually exclusive");\n'
                "\t}\n"
                "\tif (created_ts && value.status && *value.status != GetMarketsStatus::Unopened && *value.status != GetMarketsStatus::Open) {\n"
                '\t\treturn invalid("GetMarketsParams", "status", "is incompatible with created timestamp filters");\n'
                "\t}\n"
                "\tif (close_ts && value.status && *value.status != GetMarketsStatus::Closed) {\n"
                '\t\treturn invalid("GetMarketsParams", "status", "is incompatible with close timestamp filters");\n'
                "\t}\n"
                "\tif (settled_ts && value.status && *value.status != GetMarketsStatus::Settled) {\n"
                '\t\treturn invalid("GetMarketsParams", "status", "is incompatible with settled timestamp filters");\n'
                "\t}\n"
                "\tif (updated_ts) {\n"
                "\t\tif (value.status || value.event_ticker || value.tickers) {\n"
                '\t\t\treturn invalid("GetMarketsParams", "fields", "updated timestamp filters are incompatible with status, event_ticker, and tickers");\n'
                "\t\t}\n"
                "\t\tif (value.mve_filter && *value.mve_filter != GetMarketsMveFilter::Exclude) {\n"
                '\t\t\treturn invalid("GetMarketsParams", "mve_filter", "must be exclude when using updated timestamp filters");\n'
                "\t\t}\n"
                "\t\tif (value.series_ticker && (!value.mve_filter || *value.mve_filter != GetMarketsMveFilter::Exclude)) {\n"
                '\t\t\treturn invalid("GetMarketsParams", "mve_filter", "must be exclude when combining series_ticker with updated timestamp filters");\n'
                "\t\t}\n"
                "\t}\n"
            )
        if name == "GetWeatherIndexParams":
            return (
                "\tif (value.last_sec && (value.from || value.to)) {\n"
                '\t\treturn invalid("GetWeatherIndexParams", "last_sec", "cannot be combined with from or to");\n'
                "\t}\n"
            )
        if name == "GetHistoricalMarketsParams":
            return (
                "\tconst int filters = static_cast<int>(value.tickers.has_value()) + "
                "static_cast<int>(value.event_ticker.has_value()) + "
                "static_cast<int>(value.series_ticker.has_value()) + "
                "static_cast<int>(value.mve_filter.has_value());\n"
                "\tif (filters > 1) {\n"
                '\t\treturn invalid("GetHistoricalMarketsParams", "fields", "filters are mutually exclusive");\n'
                "\t}\n"
            )
        return ""

    def validate_header(self) -> str:
        names: list[str] = []
        pending = sorted(self.request_bodies | self.query_param_structs)
        while pending:
            name = pending.pop()
            if name in names or not self.needs_validation(name):
                continue
            names.append(name)
            for m in self.structs[name].members:
                if m.element in self.structs:
                    pending.append(m.element)
        order = [s.name for s in self.ordered_structs() if s.name in names]
        out = [BANNER, "#pragma once\n\n#include \"kalshi/api.hpp\"\n#include \"kalshi/fixed_point.hpp\"\n\n",
               "#include <cstddef>\n#include <string>\n#include <string_view>\n\nnamespace kalshi::detail {\n\n",
               "inline Result<void> invalid(std::string_view type, std::string_view field, std::string_view why) {\n"
               "\treturn std::unexpected(Error{ErrorCode::InvalidRequest,\n"
               "\t\t\t\t\t\t\t\t std::string(type) + \".\" + std::string(field) + \" \" + std::string(why)});\n}\n\n",
               "inline bool is_valid_client_order_id(std::string_view text) noexcept {\n"
               "\tif (text.size() > 64) {\n\t\treturn false;\n\t}\n"
               "\tfor (const char ch : text) {\n"
               "\t\tconst bool alpha = (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');\n"
               "\t\tconst bool digit = ch >= '0' && ch <= '9';\n"
               "\t\tconst bool punct = ch == '_' || ch == '-' || ch == ':' || ch == '+' || ch == '=' || ch == '/';\n"
               "\t\tif (!alpha && !digit && !punct) {\n\t\t\treturn false;\n\t\t}\n"
               "\t}\n"
               "\treturn true;\n}\n\n"]
        for name in order:
            out.append(f"inline Result<void> validate(const {name}& value);\n")
        out.append("\n")
        for name in order:
            out.append(f"inline Result<void> validate(const {name}& value) {{\n")
            for m in self.structs[name].members:
                access = f"value.{m.json_name}"
                opt = m.cpp_type.startswith("std::optional<")
                if m.fixed_point:
                    cond = f"({access} && !FixedPoint::parse(*{access}))" if opt else f"!FixedPoint::parse({access})"
                    out.append(f'\tif ({cond}) {{\n\t\treturn invalid("{name}", "{m.json_name}", "is not a fixed-point decimal");\n\t}}\n')
                elif m.fixed_point_items:
                    rng = f"*{access}" if opt else access
                    guard_open = f"\tif ({access}) {{\n" if opt else ""
                    guard_close = "\t}\n" if opt else ""
                    out.append(f"{guard_open}\tfor (const {m.fixed_point_items}& item : {rng}) {{\n"
                               "\t\tif (!FixedPoint::parse(item)) {\n"
                               f'\t\t\treturn invalid("{name}", "{m.json_name}", "has an item that is not a fixed-point decimal");\n'
                               f"\t\t}}\n\t}}\n{guard_close}")
                elif m.required and m.base_kind == "enum":
                    out.append(f'\tif ({access} == {m.element}::Unknown) {{\n\t\treturn invalid("{name}", "{m.json_name}", "is required");\n\t}}\n')
                elif m.required and m.base_kind == "string":
                    out.append(f'\tif ({access}.empty()) {{\n\t\treturn invalid("{name}", "{m.json_name}", "is required");\n\t}}\n')
                if m.minimum is not None or m.maximum is not None:
                    val_expr = f"*{access}" if opt else access
                    bounds = []
                    if m.minimum is not None:
                        bounds.append(f"{val_expr} < {m.minimum}")
                    if m.maximum is not None:
                        bounds.append(f"{val_expr} > {m.maximum}")
                    cond = f"{access} && ({' || '.join(bounds)})" if opt else " || ".join(bounds)
                    out.append(f'\tif ({cond}) {{\n\t\treturn invalid("{name}", "{m.json_name}", "is outside its allowed range");\n\t}}\n')
                if m.min_length is not None or m.max_length is not None:
                    size_expr = f"{access}->size()" if opt else f"{access}.size()"
                    bounds = []
                    if m.min_length is not None and (not m.required or m.min_length > 1):
                        bounds.append(f"{size_expr} < {m.min_length}U")
                    if m.max_length is not None:
                        bounds.append(f"{size_expr} > {m.max_length}U")
                    if bounds:
                        cond = f"{access} && ({' || '.join(bounds)})" if opt else " || ".join(bounds)
                        out.append(f'\tif ({cond}) {{\n\t\treturn invalid("{name}", "{m.json_name}", "length is outside its allowed range");\n\t}}\n')
                if m.min_items is not None or m.max_items is not None:
                    size_expr = f"{access}->size()" if opt else f"{access}.size()"
                    bounds = []
                    if m.min_items is not None:
                        if opt or m.required:
                            bounds.append(f"{size_expr} < {m.min_items}U")
                        else:
                            bounds.append(f"(!{access}.empty() && {size_expr} < {m.min_items}U)")
                    if m.max_items is not None:
                        bounds.append(f"{size_expr} > {m.max_items}U")
                    if bounds:
                        cond = f"{access} && ({' || '.join(bounds)})" if opt else " || ".join(bounds)
                        out.append(f'\tif ({cond}) {{\n\t\treturn invalid("{name}", "{m.json_name}", "size is outside its allowed range");\n\t}}\n')
                if m.element in order and m.base_kind == "struct":
                    if opt:
                        out.append(f"\tif ({access}) {{\n\t\tif (Result<void> valid = validate(*{access}); !valid) {{\n"
                                   "\t\t\treturn valid;\n\t\t}\n\t}\n")
                    else:
                        out.append(f"\tif (Result<void> valid = validate({access}); !valid) {{\n\t\treturn valid;\n\t}}\n")
                elif m.element in order and m.base_kind == "vector":
                    rng = f"*{access}" if opt else access
                    guard_open = f"\tif ({access}) {{\n" if opt else ""
                    guard_close = "\t}\n" if opt else ""
                    out.append(f"{guard_open}\tfor (const {m.element}& item : {rng}) {{\n"
                               "\t\tif (Result<void> valid = validate(item); !valid) {\n\t\t\treturn valid;\n\t\t}\n\t}\n"
                               f"{guard_close}")
            alternatives = REQUIRED_ALTERNATIVES.get(name)
            if alternatives:
                members = {m.json_name: m for m in self.structs[name].members}
                if any(field not in members or members[field].required for field in alternatives):
                    raise SystemExit(f"{name}: prose-required alternatives must be optional members")
                condition = " && ".join(f"!value.{field}" for field in alternatives)
                out.append(f'\tif ({condition}) {{\n\t\treturn invalid("{name}", "fields", "requires at least one of {" or ".join(alternatives)}");\n\t}}\n')
            exact = EXACTLY_ONE_ALTERNATIVES.get(name)
            if exact:
                members = {m.json_name: m for m in self.structs[name].members}
                if any(field not in members or members[field].required for field in exact):
                    raise SystemExit(f"{name}: prose-required alternatives must be optional members")
                a, b = exact
                out.append(f'\tif (value.{a}.has_value() == value.{b}.has_value()) {{\n'
                           f'\t\treturn invalid("{name}", "fields", "requires exactly one of {a} or {b}");\n\t}}\n')
            for pair in AT_MOST_ONE_ALTERNATIVES.get(name, ()):
                members = {m.json_name: m for m in self.structs[name].members}
                if any(field not in members or members[field].required for field in pair):
                    raise SystemExit(f"{name}: prose mutual-exclusion fields must be optional members")
                a, b = pair
                out.append(f'\tif (value.{a} && value.{b}) {{\n'
                           f'\t\treturn invalid("{name}", "fields", "allows at most one of {a} or {b}");\n\t}}\n')
            if name in CUSTOM_PROSE_VALIDATORS:
                out.append(self.emit_custom_prose_checks(name))
            schema = self.struct_schemas.get(name, {})
            if "not" in schema:
                predicates = []
                members = {m.json_name: m for m in self.structs[name].members}
                for field, constraint in schema["not"]["properties"].items():
                    access = f"value.{field}"
                    if "enum" in constraint:
                        choices = [f"{access} == {members[field].element}::{enumerator(v)}" for v in constraint["enum"]]
                        predicates.append("(" + " || ".join(choices) + ")")
                    else:
                        predicates.append(f"{access} >= {constraint['minimum']}")
                out.append(f'\tif ({" && ".join(predicates)}) {{\n\t\treturn invalid("{name}", "fields", "have a forbidden combination");\n\t}}\n')
            out.append("\treturn {};\n}\n\n")
        out.append("} // namespace kalshi::detail\n")
        return "".join(out)

    def json_meta_header(self) -> str:
        out = [BANNER, "#pragma once\n\n// Glaze adapters for generated enums: unknown strings read as Unknown.\n\n",
               '#include "kalshi/models.hpp"\n\n#include <string>\n#include <string_view>\n\n#include "../json.hpp"\n\n',
               "namespace kalshi::detail {\n\n"]
        for enum in sorted(self.enums.values(), key=lambda e: e.name):
            out.append(emit_enum_parser(enum, enum.name))
        out.append("} // namespace kalshi::detail\n\nnamespace glz {\n\n")
        for enum in sorted(self.enums.values(), key=lambda e: e.name):
            out.append(emit_enum_adapter(enum, f"kalshi::{enum.name}", f"kalshi::detail::parse_{snake(enum.name)}"))
        out.append("} // namespace glz\n")
        return "".join(out)

    def routes_test(self) -> str:
        out = [BANNER, "// Each operation checks its route or rejects an invalid default request body.\n"
               "// A request body that fails validation never reaches the transport.\n\n",
               '#include "kalshi/api.hpp"\n\n#include <gtest/gtest.h>\n#include <memory>\n#include <string>\n\n'
               '#include "support/recording_transport.hpp"\n\n',
               "using namespace kalshi; // generated tests name many model types\n\n"
               "namespace {\n\nstd::string route(const std::string& target) {\n"
               "\treturn target.substr(0, target.find('?'));\n}\n\n} // namespace\n\n"]
        for op in self.operations:
            args = [f'"p{i}"' for i, _ in enumerate(op.path_params)]
            if op.body_type:
                args.append(f"{op.body_type}{{}}")
            if op.params_struct:
                args.append(f"{op.params_struct.name}{{}}")
            path = op.path
            for i, name in enumerate(op.path_params):
                path = path.replace("{" + name + "}", f"p{i}")
            method = "DEL" if op.http_method == "DELETE" else op.http_method
            out.append(f"TEST(OperationRoutes, {op.operation_id}) {{\n"
                       "\tconst std::shared_ptr<kalshi::test::RecordingTransport> transport =\n"
                       "\t\tstd::make_shared<kalshi::test::RecordingTransport>();\n"
                       "\tkalshi::KalshiClient client(transport);\n"
                       f"\tconst {self.result_type(op)} result =\n"
                       f"\t\tclient.{op.method_name}({', '.join(args)});\n")
            if (op.body_type and self.default_is_invalid(op.body_type)) or (
                    op.params_struct and self.default_is_invalid(op.params_struct.name)):
                out.append("\tASSERT_FALSE(result.has_value());\n"
                           "\tEXPECT_EQ(result.error().code, kalshi::ErrorCode::InvalidRequest);\n"
                           "\tEXPECT_EQ(transport->calls, 0);\n}\n\n")
            else:
                out.append("\tEXPECT_TRUE(result.has_value());\n"
                           f"\tEXPECT_EQ(transport->method, kalshi::HttpMethod::{method});\n"
                           f'\tEXPECT_EQ(route(transport->target), "{path}");\n}}\n\n')
        return "".join(out)

    def operations_doc(self) -> str:
        version = self.spec.get("info", {}).get("version", "?")
        out = ["# REST operations\n\n",
               f"Covers Kalshi's Predictions OpenAPI {version} document (`spec/openapi.yaml`).\n",
               "Each row is a `KalshiClient` method.\n"]
        for tag, ops in sorted(self.tags().items()):
            out.append(f"\n## {tag}\n\n| Method | Route | C++ |\n| --- | --- | --- |\n")
            for op in ops:
                note = " (deprecated)" if op.deprecated else ""
                out.append(f"| {op.http_method} | `{op.path}` | `{op.method_name}`{note} |\n")
        return "".join(out)

    def tags(self) -> dict[str, list[Operation]]:
        by_tag: dict[str, list[Operation]] = {}
        for op in self.operations:
            by_tag.setdefault(op.tag, []).append(op)
        return by_tag


def render_api(declarations: str) -> str:
    template = (ROOT / "tools" / "codegen" / "api.hpp.in").read_text()
    return BANNER + template.replace("@OPERATIONS@\n", declarations)


def outputs(gen: Generator, ws: WsGenerator) -> dict[Path, str]:
    files = {
        ROOT / "include" / "kalshi" / "models.hpp": gen.models_header(),
        ROOT / "include" / "kalshi" / "api.hpp": render_api(gen.api_declarations()),
        ROOT / "src" / "models" / "json_meta.hpp": gen.json_meta_header(),
        ROOT / "src" / "api" / "validate.hpp": gen.validate_header(),
        ROOT / "tests" / "test_operation_routes.cpp": gen.routes_test(),
        ROOT / "docs" / "operations.md": gen.operations_doc(),
        ROOT / "include" / "kalshi" / "ws_models.hpp": ws.models_header(),
        ROOT / "src" / "ws" / "wire.hpp": ws.wire_header(),
        ROOT / "tests" / "test_ws_messages.cpp": ws.messages_test(),
        ROOT / "docs" / "channels.md": ws.channels_doc(),
    }
    for tag, ops in gen.tags().items():
        if not re.fullmatch(r"[a-z0-9_-]+", tag):
            raise SystemExit(f"tag {tag!r} cannot name a source file")
        files[ROOT / "src" / "api" / "operations" / f"{tag.replace('-', '_')}.cpp"] = gen.operations_source(tag, ops)
    return files


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="fail if generated files are stale")
    args = parser.parse_args()

    gen = Generator(load_contract_yaml(SPEC.read_text()))
    gen.run()
    ws = WsGenerator(load_contract_yaml(WS_SPEC.read_text()), gen.enums)
    ws.run()
    files = {path: clang_format(path, text) if path.suffix in (".hpp", ".cpp") else text
             for path, text in outputs(gen, ws).items()}

    stale = [path for path, text in files.items() if not path.exists() or path.read_text() != text]
    generated_dir = ROOT / "src" / "api" / "operations"
    orphans = [p for p in generated_dir.glob("*.cpp") if p not in files] if generated_dir.exists() else []
    if args.check:
        for path in stale + orphans:
            print(f"out of date: {path.relative_to(ROOT)}", file=sys.stderr)
        return 1 if stale or orphans else 0
    for path in orphans:
        path.unlink()
    for path in stale:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(files[path])
        print(f"wrote {path.relative_to(ROOT)}")
    print(f"REST: {len(gen.operations)} operations, {len(gen.structs)} structs, {len(gen.enums)} enums")
    print(f"WebSocket: {len(ws.channels)} channels, {len(ws.messages)} messages, {len(ws.structs)} structs, "
          f"{len(ws.enums)} enums")
    return 0


if __name__ == "__main__":
    sys.exit(main())
